import{_ as o,o as s,c as i,ag as t}from"./chunks/framework.DNmTgtHf.js";const h=JSON.parse('{"title":"KIE Reading Roadmap — Drools, jBPM, DMN & Kogito","description":"","frontmatter":{},"headers":[],"relativePath":"todo/my_verify_docs/kie-reading-roadmap.md","filePath":"todo/my_verify_docs/kie-reading-roadmap.md"}'),a={name:"todo/my_verify_docs/kie-reading-roadmap.md"};function n(r,e,l,d,c,g){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="kie-reading-roadmap-—-drools-jbpm-dmn-kogito" tabindex="-1">KIE Reading Roadmap — Drools, jBPM, DMN &amp; Kogito <a class="header-anchor" href="#kie-reading-roadmap-—-drools-jbpm-dmn-kogito" aria-label="Permalink to &quot;KIE Reading Roadmap — Drools, jBPM, DMN &amp; Kogito&quot;">​</a></h1><p><strong>Source:</strong> <a href="https://kie.apache.org/documentation/documentation_10.1.0/" target="_blank" rel="noreferrer">https://kie.apache.org/documentation/documentation_10.1.0/</a><strong>Goal:</strong> Build mental model bottom-up — concepts → engines (Drools, DMN, jBPM) → cloud-native runtime (Kogito).</p><hr><h2 id="mental-model-read-this-first-refer-back-often" tabindex="-1">Mental Model (read this first, refer back often) <a class="header-anchor" href="#mental-model-read-this-first-refer-back-often" aria-label="Permalink to &quot;Mental Model (read this first, refer back often)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Component</th><th>What it does</th></tr></thead><tbody><tr><td>Rules engine</td><td><strong>Drools</strong></td><td>Evaluates business rules over facts</td></tr><tr><td>Decision engine</td><td><strong>DMN engine</strong></td><td>Executes DMN models with FEEL expressions</td></tr><tr><td>Process engine</td><td><strong>jBPM</strong></td><td>Orchestrates BPMN 2.0 workflows</td></tr><tr><td>Cloud-native runtime</td><td><strong>Kogito</strong></td><td>Wraps all three for Quarkus / Spring Boot / Kubernetes</td></tr></tbody></table><p><strong>Rule of thumb:</strong> Kogito is <em>not</em> a replacement for Drools/jBPM/DMN — it&#39;s a modern packaging of them. Learn the engines first, Kogito clicks faster.</p><hr><h2 id="phase-1-—-lay-of-the-land-1⁄2-day" tabindex="-1">Phase 1 — Lay of the Land (½ day) <a class="header-anchor" href="#phase-1-—-lay-of-the-land-1⁄2-day" aria-label="Permalink to &quot;Phase 1 — Lay of the Land (½ day)&quot;">​</a></h2><ul><li>[ ] KIE ecosystem overview — what each component is and how they fit</li><li>[ ] Difference between <strong>rules</strong>, <strong>decisions</strong>, and <strong>processes</strong> (don&#39;t skip — this trips people up later)</li><li>[ ] Authoring vs runtime — KIE projects, KJARs, KieBase, KieSession concepts at a high level</li></ul><hr><h2 id="phase-2-—-drools-rules-engine-2–3-days" tabindex="-1">Phase 2 — Drools (Rules Engine) (2–3 days) <a class="header-anchor" href="#phase-2-—-drools-rules-engine-2–3-days" aria-label="Permalink to &quot;Phase 2 — Drools (Rules Engine) (2–3 days)&quot;">​</a></h2><p>The foundation. Kogito&#39;s rules support sits on top of this.</p><ul><li>[ ] Rule engine fundamentals — facts, working memory, agenda, Rete (high-level only)</li><li>[ ] <strong>DRL (Drools Rule Language)</strong> syntax <ul><li>[ ] <code>when</code> / <code>then</code> structure</li><li>[ ] Patterns, constraints, bindings</li><li>[ ] <code>accumulate</code>, <code>collect</code>, <code>exists</code>, <code>not</code></li><li>[ ] Salience, agenda groups, rule attributes</li></ul></li><li>[ ] <strong>Runtime model</strong> — KieBase, KieSession (stateful vs stateless), KieContainer</li><li>[ ] Authoring options <ul><li>[ ] DRL files</li><li>[ ] Decision tables (spreadsheet-based)</li><li>[ ] Guided rules / guided decision tables</li></ul></li><li>[ ] Testing — scenario simulation, unit tests</li><li>[ ] <em>(Optional)</em> Complex Event Processing (CEP) — only if your use case needs temporal reasoning over event streams</li></ul><hr><h2 id="phase-3-—-dmn-decisions-1-day" tabindex="-1">Phase 3 — DMN (Decisions) (1 day) <a class="header-anchor" href="#phase-3-—-dmn-decisions-1-day" aria-label="Permalink to &quot;Phase 3 — DMN (Decisions) (1 day)&quot;">​</a></h2><p>The cleaner, standardized way to model decisions. Often preferable to raw DRL for business-readable logic.</p><ul><li>[ ] DMN spec basics — Decision Requirements Diagram (DRD)</li><li>[ ] <strong>FEEL</strong> expression language — syntax, built-in functions</li><li>[ ] DMN decision tables (vs Drools decision tables — when to use which)</li><li>[ ] Boxed expressions — context, invocation, list, relation</li><li>[ ] Testing DMN models</li></ul><hr><h2 id="phase-4-—-jbpm-processes-2-days" tabindex="-1">Phase 4 — jBPM (Processes) (2 days) <a class="header-anchor" href="#phase-4-—-jbpm-processes-2-days" aria-label="Permalink to &quot;Phase 4 — jBPM (Processes) (2 days)&quot;">​</a></h2><p>The process engine. Kogito&#39;s process support is the cloud-native evolution of this.</p><ul><li>[ ] <strong>BPMN 2.0 fundamentals</strong> — tasks, gateways, events, lanes, pools</li><li>[ ] jBPM engine basics — process instances, runtime manager, KieSession for processes</li><li>[ ] Process variables and data flow between tasks</li><li>[ ] <strong>Human tasks</strong> — task lifecycle, assignment, task service</li><li>[ ] Sub-processes, signals, timers, boundary events, error handling</li><li>[ ] Persistence — process state, history logs, audit</li><li>[ ] Integration points — calling Drools rules and DMN decisions <em>from</em> a process</li></ul><blockquote><p><strong>Skip-if-going-straight-to-Kogito:</strong> Business Central / KIE Workbench UI tooling, jBPM-specific REST kie-server APIs, and older form modeler — Kogito replaces these. Keep your focus on <strong>engine concepts</strong>, not classic jBPM tooling.</p></blockquote><hr><h2 id="phase-5-—-kogito-cloud-native-runtime-3-days" tabindex="-1">Phase 5 — Kogito (Cloud-Native Runtime) (3+ days) <a class="header-anchor" href="#phase-5-—-kogito-cloud-native-runtime-3-days" aria-label="Permalink to &quot;Phase 5 — Kogito (Cloud-Native Runtime) (3+ days)&quot;">​</a></h2><p>Now you have the building blocks. Kogito is <em>how you ship them.</em></p><ul><li>[ ] Kogito architecture overview</li><li>[ ] Quarkus integration (primary) — also Spring Boot integration</li><li>[ ] Build a first Kogito service combining a rule + a decision + a process</li><li>[ ] <strong>Serverless Workflow</strong> (CNCF spec) — Kogito&#39;s modern, lighter-weight process flavor (alternative to BPMN for many cases)</li><li>[ ] Supporting services <ul><li>[ ] Persistence (Infinispan, MongoDB, PostgreSQL options)</li><li>[ ] Jobs Service (timers, scheduled work)</li><li>[ ] Data Index (querying process/decision data)</li><li>[ ] Trusty Service / Explainability (if relevant)</li></ul></li><li>[ ] Deployment — container images, Kubernetes Operator, OpenShift</li><li>[ ] Observability — metrics, tracing, logs</li><li>[ ] Code generation model — how Kogito turns BPMN/DMN/DRL into Java at build time</li></ul><hr><h2 id="capstone-—-build-something-end-to-end" tabindex="-1">Capstone — Build Something End-to-End <a class="header-anchor" href="#capstone-—-build-something-end-to-end" aria-label="Permalink to &quot;Capstone — Build Something End-to-End&quot;">​</a></h2><p>After Phase 5, build a small project to cement everything. Suggested example:</p><blockquote><p><strong>Loan approval service:</strong> Drools rules check applicant eligibility → DMN decides interest rate → BPMN process orchestrates the whole flow including a human task for manual review on edge cases → deploy as a Kogito service on Quarkus.</p></blockquote><p>This forces you to wire all four pieces together and surfaces the gaps in your understanding.</p><hr><h2 id="reading-tips" tabindex="-1">Reading Tips <a class="header-anchor" href="#reading-tips" aria-label="Permalink to &quot;Reading Tips&quot;">​</a></h2><ul><li>Don&#39;t memorize syntax in Phase 2 — understand the <em>shape</em> of DRL. Real fluency comes when you build in Phase 5.</li><li>If your use case is rules/decisions only, you can defer Phase 4 (jBPM/BPMN) and come back later.</li><li>When the docs use the term &quot;KIE Server&quot; — that&#39;s the classic deployment model; Kogito services replace it for cloud-native deployments.</li><li>Keep this checklist open in a side pane. Tick items as you go — visible progress is motivating across a multi-day read.</li></ul><hr><h2 id="quick-glossary" tabindex="-1">Quick Glossary <a class="header-anchor" href="#quick-glossary" aria-label="Permalink to &quot;Quick Glossary&quot;">​</a></h2><ul><li><strong>KIE</strong> — Knowledge Is Everything; umbrella project for Drools/jBPM/etc.</li><li><strong>KJAR</strong> — Kie JAR; deployable artifact containing rules/processes/decisions.</li><li><strong>DRL</strong> — Drools Rule Language.</li><li><strong>DMN</strong> — Decision Model and Notation (OMG standard).</li><li><strong>BPMN</strong> — Business Process Model and Notation (OMG standard).</li><li><strong>FEEL</strong> — Friendly Enough Expression Language (DMN&#39;s expression language).</li><li><strong>CEP</strong> — Complex Event Processing.</li><li><strong>CNCF Serverless Workflow</strong> — open spec for declarative workflows; supported by Kogito alongside BPMN.</li></ul>',37)])])}const p=o(a,[["render",n]]);export{h as __pageData,p as default};
